function publicBody(m){
 const outdoor=['village','ruin','settlement'].includes(m.kind);
 let b=`<rect x="-1000" y="-1000" width="4000" height="4000" fill="${outdoor?'url(#grass)':'url(#earth)'}"/>`;
 for(const x of m.landscape||[])b+=x;
 if(m.roads)for(const d of m.roads)b+=`<path d="${d}" fill="none" stroke="#b4ad8c" stroke-width="${m.roadWidth||37}" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#c4b99a" stroke-width="${(m.roadWidth||37)-10}" stroke-linecap="round"/>`;
 for(const d of m.corridors)b+=floor(d);
 for(const r of m.rooms)if(m.kind!=='settlement')b+=r.open||r.ruined?`<path d="${r.d}" fill="${r.open?'#bab193':'url(#stone)'}"/>`:floor(r.d);
 for(const x of m.features)b+=x;
 for(const x of m.props)b+=x;
 for(const[x,y,o,w=28]of m.openings||[]){const h=o==='h';b+=`<path d="M${x-(h?w/2:0)} ${y-(h?0:w/2)}l${h?w:0} ${h?0:w}" stroke="#c6c2aa" stroke-width="12"/>`;}
 for(const[x,y,o,w=26]of m.doors){const horizontal=o==='h'; b+=`<path d="M${x-(horizontal?w/2:0)} ${y-(horizontal?0:w/2)}l${horizontal?w:0} ${horizontal?0:w}" stroke="#c6c2aa" stroke-width="12"/>`;
 // Thresholds, with no lock/secret/occupant markers.
 b+=horizontal?rect(x-w/2,y-2,w,4,'#7e6b4d',0):rect(x-2,y-w/2,4,w,'#7e6b4d',0);}
 return b;
}
